using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class MobileStatsAuthoring {
 const string Request="Logs/MobileStats.request",Logs="Logs/MobileStats";static int checks;
 static void Check(bool ok,string message){if(!ok)throw new InvalidOperationException("Mobile stats: "+message);checks++;}
 static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
 [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
 static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Install();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
 static RectTransform Rect(string name,Transform parent,Vector2 anchor,Vector2 pivot,Vector2 position,Vector2 size){var found=parent.Find(name);var r=found?(RectTransform)found:new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=anchor;r.pivot=pivot;r.anchoredPosition=position;r.sizeDelta=size;r.localScale=Vector3.one;return r;}
 static T Component<T>(GameObject go)where T:Component=>go.GetComponent<T>()?go.GetComponent<T>():go.AddComponent<T>();
 static Text Label(RectTransform rect,Font font,int size,TextAnchor alignment){var t=Component<Text>(rect.gameObject);t.font=font;t.fontSize=size;t.color=Color.white;t.alignment=alignment;t.raycastTarget=false;t.supportRichText=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Truncate;return t;}
 public static void Apply(PrototypeHUD hud){
  var root=Rect("Mobile performance stats | authored",hud.safeArea,new Vector2(.5f,.5f),new Vector2(.5f,.5f),Vector2.zero,Vector2.zero);root.anchorMin=Vector2.zero;root.anchorMax=Vector2.one;root.offsetMin=root.offsetMax=Vector2.zero;
  var stats=Component<MobilePerformanceStats>(root.gameObject);stats.safeArea=hud.safeArea;
  var group=Rect("Stats button anchor",root,new Vector2(.95f,1),Vector2.one,Vector2.zero,Vector2.zero);stats.buttonGroup=group;
  var buttonRect=Rect("Toggle performance stats",group,Vector2.one,Vector2.one,new Vector2(0,-58),new Vector2(96,44));
  var image=Component<Image>(buttonRect.gameObject);image.sprite=AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");image.type=Image.Type.Sliced;image.color=new Color(.035f,.25f,.29f,.95f);image.raycastTarget=true;
  var button=Component<Button>(buttonRect.gameObject);button.targetGraphic=image;button.navigation=new Navigation{mode=Navigation.Mode.None};button.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(button.onClick,stats.Toggle);stats.toggleButton=button;
  var labelRect=Rect("Label",buttonRect,new Vector2(.5f,.5f),new Vector2(.5f,.5f),Vector2.zero,Vector2.zero);labelRect.anchorMin=Vector2.zero;labelRect.anchorMax=Vector2.one;labelRect.offsetMin=new Vector2(4,4);labelRect.offsetMax=new Vector2(-4,-4);stats.buttonLabel=Label(labelRect,hud.status.font,16,TextAnchor.MiddleCenter);stats.buttonLabel.text="STATS";
  var panel=Rect("Performance readout",root,new Vector2(.5f,1),new Vector2(.5f,1),new Vector2(0,-72),new Vector2(444,274));stats.readoutRect=panel;stats.readout=panel.gameObject;
  var background=Component<Image>(panel.gameObject);background.color=new Color(.015f,.07f,.09f,.85f);background.raycastTarget=false;
  var textRect=Rect("Readout text",panel,new Vector2(.5f,.5f),new Vector2(.5f,.5f),Vector2.zero,Vector2.zero);textRect.anchorMin=Vector2.zero;textRect.anchorMax=Vector2.one;textRect.offsetMin=new Vector2(12,10);textRect.offsetMax=new Vector2(-12,-10);stats.readoutText=Label(textRect,hud.status.font,16,TextAnchor.UpperLeft);stats.readoutText.lineSpacing=1.05f;
  stats.readoutText.text="PERFORMANCE | FPS / frame time / memory / rendering";panel.gameObject.SetActive(false);EditorUtility.SetDirty(stats);EditorUtility.SetDirty(hud);
 }
 static void Validate(PrototypeHUD hud){var stats=hud.safeArea.GetComponentsInChildren<MobilePerformanceStats>(true);Check(stats.Length==1,"one stats module");var s=stats[0];Check(s.safeArea==hud.safeArea&&s.toggleButton&&s.buttonLabel&&s.readoutText&&s.readoutRect,"saved bindings");Check(!s.readout.activeSelf,"default hidden");Check(s.toggleButton.onClick.GetPersistentEventCount()==1&&s.toggleButton.onClick.GetPersistentTarget(0)==s&&s.toggleButton.onClick.GetPersistentMethodName(0)=="Toggle","persistent button binding");Check(!s.readout.GetComponentsInChildren<Graphic>(true).Any(g=>g.raycastTarget),"readout blocks driving/orbit input");Check(s.buttonGroup.anchorMin==new Vector2(.95f,1),"safe area margin");Check(s.readoutText.fontSize==16&&s.buttonLabel.fontSize==16,"mobile font sizes");}
 static void Tests(PrototypeHUD hud){
  var f=new PerformanceFrameWindow();for(int i=0;i<150;i++)f.Add(1f/30);Check(Math.Abs(f.Fps-30)<.001&&Math.Abs(f.AverageMs-33.33333)<.001,"30 FPS window");Check(Math.Abs(f.Percentile99Ms()-33.33333)<.001,"p99 constant");f.Clear();for(int i=0;i<100;i++)f.Add(i==99?.1f:.01f);Check(Math.Abs(f.AverageMs-10.9)<.001,"weighted mean");Check(Math.Abs(f.Percentile99Ms()-10)<.001,"p99 rank");f.Add(.2f);Check(Math.Abs(f.Percentile99Ms()-100)<.001,"p99 hitch");f.Clear();for(int i=0;i<1000;i++)f.Add(.01f);Check(f.Duration<=5.02&&f.Count<=502,"five second eviction");f.Clear();f.Add(float.NaN);f.Add(float.PositiveInfinity);f.Add(0);f.Add(-1);Check(f.Count==0,"invalid samples");for(int i=0;i<5000;i++)f.Add(.0001f);Check(f.Count==2048,"bounded high FPS ring");f.Clear();Check(f.Count==0&&f.AverageMs==0,"reset");Check(MobilePerformanceStats.CounterText(false,0)=="n/a"&&MobilePerformanceStats.CounterText(true,0)=="0","unavailable versus zero");
  var s=hud.safeArea.GetComponentInChildren<MobilePerformanceStats>(true);var callState=s.toggleButton.onClick.GetPersistentListenerState(0);s.toggleButton.onClick.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);try{s.toggleButton.onClick.Invoke();Check(s.Visible&&s.readout.activeSelf,"button opens");s.RefreshDisplay();Check(s.readoutText.text.Contains("FPS")&&s.readoutText.text.Contains("CPU")&&s.readoutText.text.Contains("Unity memory")&&s.readoutText.text.Contains("Tris"),"stats readout");s.toggleButton.onClick.Invoke();Check(!s.Visible&&!s.readout.activeSelf&&s.RecorderCount==0,"button closes and disposes");s.SetVisible(true);typeof(MobilePerformanceStats).GetMethod("OnApplicationPause",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,new object[]{true});Check(s.RecorderCount==0,"background disposes counters");typeof(MobilePerformanceStats).GetMethod("OnApplicationPause",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,new object[]{false});s.SetVisible(false);Check(s.RecorderCount==0,"resume/hide cleanup");}finally{s.SetVisible(false);s.toggleButton.onClick.SetPersistentListenerState(0,callState);}
 }
 [MenuItem("Snowglow/UI/Install mobile performance stats toggle")]
 public static void Install(){checks=0;Directory.CreateDirectory(Logs);var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Pinefall with Play stopped");if(!File.Exists(Logs+"/Pinefall-before.unity"))EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before.unity",true);if(scene.isDirty)EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true);
  var hud=All<PrototypeHUD>(scene).Single();var session=All<PrototypeSession>(scene).Single();string seed=AssetDatabase.GetAssetPath(session.Snow.seed);var hash=AssetDatabase.GetAssetDependencyHash(seed);var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>p.transform.localToWorldMatrix.ToString("R"));var fleet=session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).ToArray();
  Apply(hud);Validate(hud);Tests(hud);Apply(hud);Validate(hud);SceneValidation.Validate(scene);MechanicsChecks.Run();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);hud=All<PrototypeHUD>(scene).Single();Validate(hud);session=All<PrototypeSession>(scene).Single();Check(seed==AssetDatabase.GetAssetPath(session.Snow.seed)&&hash==AssetDatabase.GetAssetDependencyHash(seed),"snow changed");foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==p.transform.localToWorldMatrix.ToString("R"),"scenery moved");Check(fleet.SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"fleet moved");SceneValidation.Validate(scene);
  // Existing native HUD renderer produces a saved, reviewable layout image.
  var stats=hud.safeArea.GetComponentInChildren<MobilePerformanceStats>(true);try{stats.SetVisible(true);stats.RefreshDisplay();typeof(CompactHUDAuthoring).GetMethod("Preview",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{hud});File.Copy("Logs/CompactHUD/Preview.png",Logs+"/Preview.png",true);}finally{stats.SetVisible(false);EditorSceneManager.OpenScene(SceneValidation.ScenePath);}
  File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+"; "+checks+" checks. Saved/reopened safe-area STATS toggle with persistent click handler, default-hidden non-raycasting overlay. Rolling five-second wall-clock FPS/mean/p99, optional CPU/GPU/memory/render counters, n/a fallback, zero-value distinction, hide/background disposal and bounded sample storage checked. Existing scene/19 snow checks passed; snow seed hash and forest/catalog/fleet poses unchanged. Native HUD preview generated. No runtime UI factories, save-schema changes, geometry changes or player-save writes. Actual mobile taps/counter availability, live Play timing accuracy and Android packaging/device performance untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
 }
 }
